:root {
  color-scheme: light dark;
  --art-bg: #f5f7fb;
  --art-surface: rgba(255, 255, 255, 0.92);
  --art-surface-raised: #ffffff;
  --art-ink: #17202b;
  --art-muted: #647184;
  --art-accent: #5b5bd6;
  --art-accent-strong: #4343b8;
  --art-accent-soft: rgba(91, 91, 214, 0.13);
  --art-good: #16805c;
  --art-good-soft: rgba(22, 128, 92, 0.11);
  --art-warn: #a86500;
  --art-warn-soft: rgba(168, 101, 0, 0.12);
  --art-bad: #b84955;
  --art-bad-soft: rgba(184, 73, 85, 0.11);
  --art-border: rgba(68, 83, 112, 0.14);
  --art-grid: rgba(82, 96, 128, 0.07);
  --art-radius: 20px;
  --art-radius-sm: 12px;
  --art-shadow: 0 18px 50px rgba(36, 47, 72, 0.09);
  --art-font: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

