    --art-surface: rgba(25, 31, 42, 0.94);
    --art-surface-raised: #1d2532;
    --art-ink: #edf2fb;
    --art-muted: #a1aec2;
    --art-accent: #9b9bf7;
    --art-accent-strong: #b7b7ff;
    --art-accent-soft: rgba(155, 155, 247, 0.16);
    --art-good: #62d5a8;
    --art-good-soft: rgba(98, 213, 168, 0.13);
