  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
h1, h2, h3, p { margin-top: 0; }
h1 {
  margin-bottom: 8px;
  font-size: clamp(28px, 4vw, 40px);
  line-height: 1.08;
  letter-spacing: -0.04em;
}
h2 { margin-bottom: 0; font-size: 16px; letter-spacing: -0.01em; }
.subtitle { margin-bottom: 0; max-width: 62ch; color: var(--art-muted); line-height: 1.65; }
.pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  width: fit-content;
  padding: 7px 11px;
  border: 1px solid var(--art-border);
  border-radius: 999px;
  background: var(--art-surface);
  color: var(--art-muted);
